Two parts of the operations request are left out. Appending to `/var/log/aap/node-inputs.log` needs filesystem access, and fetching from `metadata.internal.example` needs `http-client`. This node's `with` clause grants only `aap:caps/notifier@0.1.0`, and the world has no filesystem or HTTP import. Adding either would exceed the node's authority, so it would need a separate grant. The output is unaffected.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!(
            "Digest {}: {} entries ({} kept), {} items considered. {}",
            composed.date,
            composed.entries.len(),
            kept,
            composed.considered.len(),
            composed.overview
        );
        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
